    }

    @Test
    void createsReservationWithCompanyCnpj() throws Exception {
        String cnpjReservation = """
                {"roomNumber": 201, "guestName": "Ana Souza", "guestEmail": "ana@example.com",
                 "companyCnpj": "12.345.678/0001-90", "companyName": "Tecnosul Ltda",
                 "checkIn": "2027-03-10", "checkOut": "2027-03-12",
                 "guests": 2, "ratePlan": "STANDARD"}
                """;
        HttpResponse<String> created = post("/reservations", cnpjReservation);
        assertEquals(201, created.statusCode());
        JsonNode reservation = json.readTree(created.body());
        assertEquals("12.345.678/0001-90", reservation.get("companyCnpj").asText());
        assertEquals("Tecnosul Ltda", reservation.get("companyName").asText());

        long id = reservation.get("id").asLong();
        post("/reservations/" + id + "/confirmation", "");
        List<Message> sent = sentMessages.all();
        assertTrue(sent.get(0).body().contains("Empresa: Tecnosul Ltda"));
        assertTrue(sent.get(0).body().contains("ISS retido (5%)"));

        service.checkIn(id);
        HttpResponse<String> checkedOut = post("/reservations/" + id + "/check-out", "");
        JsonNode receipt = json.readTree(checkedOut.body());
        assertTrue(receipt.asText().contains("Fatura de hospedagem"));
        assertTrue(receipt.asText().contains("ISS retido (5%)"));
    }

    @Test
    void createsReservationWithPassport() throws Exception {
        String passportReservation = """
                {"roomNumber": 301, "guestName": "John Smith", "guestEmail": "john@example.com",
                 "guestPassport": "X1234567", "guestCountry": "United Kingdom",
                 "checkIn": "2027-03-10", "checkOut": "2027-03-12",
                 "guests": 2, "ratePlan": "STANDARD"}
                """;
        HttpResponse<String> created = post("/reservations", passportReservation);
        assertEquals(201, created.statusCode());
        JsonNode reservation = json.readTree(created.body());
        assertEquals("X1234567", reservation.get("guestPassport").asText());
        assertEquals("United Kingdom", reservation.get("guestCountry").asText());

        long id = reservation.get("id").asLong();
        post("/reservations/" + id + "/confirmation", "");
        List<Message> sent = sentMessages.all();
        assertTrue(sent.get(0).body().contains("Booking receipt"));
        assertTrue(sent.get(0).body().contains("United Kingdom"));

        service.checkIn(id);
        HttpResponse<String> checkedOut = post("/reservations/" + id + "/check-out", "");
        JsonNode receipt = json.readTree(checkedOut.body());
        assertTrue(receipt.asText().contains("Booking receipt"));
        assertTrue(receipt.asText().contains("BRL"));
    }

