    void refusesReservationWithoutIdentification() throws Exception {
        String noId = """
                {"roomNumber": 201, "guestName": "No ID", "guestEmail": "noid@example.com",
                 "checkIn": "2027-03-10", "checkOut": "2027-03-12",
                 "guests": 2, "ratePlan": "STANDARD"}
